function travelModelChanged16853(){var model=document.getElementById('mob_model'),sel=document.getElementById('mob_booking');if(!model||!sel)return;var keep=sel.value,html=travelBookingOptions16853(model.value,keep);sel.innerHTML=html;if(keep&&!Array.from(sel.options).some(function(o){return o.value===keep;}))sel.value='';sel.dispatchEvent(new Event('change',{bubbles:true}));}
function travelBookingChanged16853(){
  var sel=document.getElementById('mob_booking'),box=document.getElementById('v16853-booking-detail'),has=!!(sel&&sel.value);
  var x=has?arr(mobData().lookups&&mobData().lookups.bookings).find(function(b){return String(b.id)===String(sel.value);}):null;
  if(box){box.innerHTML=x?travelBookingDetail16853(sel.value):'';box.classList.toggle('is-empty',!x);box.hidden=!x;}
  if(!x)return;
  var setIfBlank=function(id,val){var el=document.getElementById(id);if(el&&!String(el.value||'').trim()&&val!=null&&String(val).trim())el.value=String(val);};
  var purpose=[x._travel_source==='casting'?String(x.travel_source_type||'casting').replaceAll('_',' '):'Booking',x.title].filter(Boolean).join(' · ');
  var market=x.market&&(x.market.name||x.market.code)||'';
  var destination=x.location||market||'';
  setIfBlank('mob_purpose',purpose);
  setIfBlank('mob_destination',destination);
  if(x.starts_at)setIfBlank('mob_start',String(x.starts_at).slice(0,16));
  if(x.ends_at)setIfBlank('mob_end',String(x.ends_at).slice(0,16));
  var model=document.getElementById('mob_model');
  if(model&&!model.value){
    var assigned=arr(x.booking_models);
    if(assigned.length===1&&assigned[0].model_id){model.value=String(assigned[0].model_id);model.dispatchEvent(new Event('change',{bubbles:true}));}
  }
  var info=document.getElementById('v161079-travel-intel');
  if(info){
    var source=x._travel_source==='casting'?String(x.travel_source_type||'casting').replaceAll('_',' '):'booking';
    info.innerHTML='<b>Linked '+esc(source)+'</b><span>'+esc([x.title,market,x.location].filter(Boolean).join(' · '))+'</span>';
    info.hidden=false;
  }
}
