function visaTaskCountry(t){var txt=((t&&t.title)||'')+' '+((t&&t.description)||'')+' '+JSON.stringify((t&&t.metadata)||{});txt=txt.toLowerCase();if(/french|france|paris|schengen/.test(txt))return'FR';if(/united states|u\.s\.|us consulate|o-?1\b/.test(txt))return'US';if(/united kingdom|uk visa|british/.test(txt))return'GB';return'';}
function visaTaskStatus(t){var txt=(((t&&t.title)||'')+' '+((t&&t.description)||'')).toLowerCase();if(/interview|appointment/.test(txt))return'appointment_pending';if(/document|passport|packet|submit/.test(txt))return'gathering_documents';return'not_started';}
function visaTaskMember(t){var key=String(t&&t.metadata&&t.metadata.legacy_to_key||t&&t.metadata&&t.metadata.legacy_payload&&t.metadata.legacy_payload.toKey||'').toLowerCase();var ms=arr(mobData().lookups&&mobData().lookups.members);var found=ms.find(function(m){return String(m&&m.metadata&&m.metadata.legacy_staff_key||'').toLowerCase()===key;});return found&&found.id||'';}
